#!/bin/bash -p
# Bootgly CLI wrapper (auto-generated by: php bootgly setup)
# bootgly-wrapper: walk-up
#
# The nearest trusted Bootgly launcher above the working directory runs, so
# this command operates on that workspace. Without one, the launcher recorded
# when setup generated this wrapper is used.
#
# This global convenience wrapper is deliberately unprivileged. PHP bootstraps,
# Composer autoloaders, projects and configuration are executable code beyond
# the entrypoint itself, so the wrapper never promotes any of them to EUID 0.
#
# The tracing JIT is forced on: it cannot be enabled after PHP starts,
# and Bootgly's hot path is measurably slower without it.
# Opt out with BOOTGLY_JIT=0 (required by the native coverage driver).
BINARY=__BOOTGLY_PHP_BINARY__
SCRIPT=__BOOTGLY_FALLBACK_LAUNCHER__
# ? Root is refused before any program runs: nothing found through PATH may
#   execute as root first
if [ "${EUID:-0}" = 0 ] || [ "${UID:-0}" = 0 ]; then
   echo 'Refusing to run the Bootgly global wrapper as root.' >&2
   echo 'Use Linux capabilities, a reverse proxy, or invoke an entirely root-controlled deployment explicitly.' >&2
   exit 126
fi
# ! Then the kernel's answer: bash imports an exported EUID from the
#   environment (even with -p), so $EUID alone could hide a real root
CALLER_UID="$(id -u 2>/dev/null)"

if ! [[ "$CALLER_UID" =~ ^[0-9]+$ ]]; then
   echo 'Refusing to run the Bootgly global wrapper: the caller UID is unknown.' >&2
   exit 126
fi
if [ "$CALLER_UID" -eq 0 ]; then
   echo 'Refusing to run the Bootgly global wrapper as root.' >&2
   echo 'Use Linux capabilities, a reverse proxy, or invoke an entirely root-controlled deployment explicitly.' >&2
   exit 126
fi

canonical () {
   readlink -f -- "$1" 2>/dev/null
}

# ! One `ls -nd` line per path — its type, mode and NUMERIC owner — read the
#   same from GNU, BSD (macOS) and BusyBox (Alpine) tools: find's -uid is
#   GNU-only, and -user resolves a login NAME before the number. Sets the
#   caller's KIND, MODE and OWNER; anything unexpected fails closed.
inspect () {
   local LINE

   LINE="$(ls -nd -- "$1" 2>/dev/null)" || return 1
   [[ "$LINE" =~ ^([-d])([-rwxsStT]{9})([.+@]?)[[:space:]]+[0-9]+[[:space:]]+([0-9]+)[[:space:]] ]] || return 1
   KIND="${BASH_REMATCH[1]}"
   MODE="${BASH_REMATCH[2]}"
   OWNER="${BASH_REMATCH[4]}"
   # ? Darwin's extended ACLs grant writes no mode bit shows
   if [ "${BASH_REMATCH[3]}" = '+' ] && [[ "$OSTYPE" == darwin* ]]; then
      return 1
   fi
}

trusted () {
   local TARGET="$1"
   local CURRENT=''
   local DIRECT_PARENT=1
   local KIND=''
   local MODE=''
   local OWNER=''

   [ -n "$TARGET" ] || return 1

   # @ A regular file, owned by the caller or root, writable by neither group
   #   nor other
   inspect "$TARGET" || return 1
   [ "$KIND" = '-' ] || return 1
   [ "$OWNER" = 0 ] || [ "$OWNER" = "$CALLER_UID" ] || return 1
   [ "${MODE:4:1}" != w ] && [ "${MODE:7:1}" != w ] || return 1

   # @ The direct parent may contain executable sibling bootstraps, so it is
   #   never allowed to be writable. Higher root-owned sticky directories
   #   (normally /tmp) are safe because the checked child cannot be replaced.
   CURRENT="${TARGET%/*}"
   [ -n "$CURRENT" ] || CURRENT='/'
   while :; do
      inspect "$CURRENT" || return 1
      [ "$KIND" = d ] || return 1
      [ "$OWNER" = 0 ] || [ "$OWNER" = "$CALLER_UID" ] || return 1
      if [ "${MODE:4:1}" = w ] || [ "${MODE:7:1}" = w ]; then
         [ "$DIRECT_PARENT" -eq 0 ] && [ "$OWNER" = 0 ] && [[ "${MODE:8:1}" == [tT] ]] || return 1
      fi
      [ "$CURRENT" = '/' ] && return 0

      DIRECT_PARENT=0
      CURRENT="${CURRENT%/*}"
      [ -n "$CURRENT" ] || CURRENT='/'
   done
}

BINARY="$(canonical "$BINARY")"
if [ -z "$BINARY" ] || [ ! -x "$BINARY" ] || ! trusted "$BINARY"; then
   echo 'Refusing to execute an untrusted Bootgly PHP binary.' >&2
   exit 126
fi

DIR="$(pwd -P)" || {
   echo 'Refusing to resolve the Bootgly working directory.' >&2
   exit 126
}
while [ -n "$DIR" ]; do
   SOURCE="$DIR/bootgly"
   CANDIDATE="$(canonical "$SOURCE")"
   if [ -n "$CANDIDATE" ] && trusted "$CANDIDATE" && grep -q "define('BOOTGLY_WORKING_BASE'" "$CANDIDATE" 2>/dev/null; then
      SCRIPT="$CANDIDATE"
      break
   fi
   [ "$DIR" = "/" ] && break
   DIR="${DIR%/*}"
   [ -n "$DIR" ] || DIR="/"
done

SCRIPT="$(canonical "$SCRIPT")"
if [ -z "$SCRIPT" ] || ! trusted "$SCRIPT"; then
   echo 'Refusing to execute an untrusted Bootgly launcher.' >&2
   exit 126
fi

if [ "${BOOTGLY_JIT:-1}" = "0" ]; then
   exec "$BINARY" -d opcache.jit=disable "$SCRIPT" "$@"
fi
exec "$BINARY" -d opcache.enable=1 -d opcache.enable_cli=1 -d opcache.jit=tracing -d opcache.jit_buffer_size=256M "$SCRIPT" "$@"
